<?php
declare(strict_types=1);
require_once __DIR__.'/branch-team.php';
function supervisor_team(PDO $db,int $user): ?array {return stock_query($db,'SELECT id,owner_id,name,revision FROM supervisor_teams WHERE owner_id=? AND active=1',[$user])->fetch()?:null;}
function supervisor_require(PDO $db,int $user): array {$team=supervisor_team($db,$user);if(!$team)throw new CatalogException('No tenés un equipo de empresa habilitado.',403);return $team;}
function supervisor_links(PDO $db,int $user): array {$rows=stock_query($db,"SELECT m.team_id,m.status,m.revision,t.name,t.active,u.public_name,u.name AS supervisor_name FROM supervisor_members m JOIN supervisor_teams t ON t.id=m.team_id JOIN users u ON u.id=t.owner_id WHERE m.user_id=? AND m.status IN ('pending','accepted') ORDER BY t.name,t.id",[$user])->fetchAll();foreach($rows as&$r){$r['supervisor_name']=get_public_user_name(['public_name'=>$r['public_name'],'name'=>$r['supervisor_name']]);unset($r['public_name']);}unset($r);return $rows;}
function supervisor_enable(PDO $db,int $actor,array $input): void {
 team_require_assignment($db,$actor);$email=mb_strtolower(trim($input['email']??''));$name=catalog_text($input['name']??'',100);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$name==='')throw new CatalogException('Completá la empresa y el correo del supervisor.',422);
 $owner=stock_query($db,'SELECT id FROM users WHERE LOWER(email)=?',[$email])->fetchColumn();if(!$owner)throw new CatalogException('Esa persona todavía no tiene una cuenta.',404);
 $previous=stock_query($db,'SELECT id,active FROM supervisor_teams WHERE owner_id=?',[$owner])->fetch();
 stock_query($db,'INSERT INTO supervisor_teams(owner_id,name) VALUES(?,?) ON CONFLICT(owner_id) DO UPDATE SET name=excluded.name,active=1,revision=supervisor_teams.revision+1',[$owner,$name]);
 if(!$previous||!(int)$previous['active']){$team=supervisor_team($db,(int)$owner);stock_query($db,'INSERT INTO notifications(user_id,event_key,type,title,body) VALUES(?,?,?,?,?)',[$owner,'supervisor-enabled:'.$team['id'].':'.$team['revision'],'supervisor_enabled','Tu equipo de empresa está habilitado',$name.' · Ya podés invitar integrantes y consultar su stock cuando acepten.']);}
}
function supervisor_disable(PDO $db,int $actor,int $team,int $revision):void {team_require_assignment($db,$actor);if(!stock_query($db,'UPDATE supervisor_teams SET active=0,revision=revision+1 WHERE id=? AND revision=? AND active=1',[$team,$revision])->rowCount())throw new CatalogException('La empresa cambió. Actualizá la lista.',409);stock_query($db,"UPDATE supervisor_members SET status='revoked',revision=revision+1 WHERE team_id=? AND status IN ('pending','accepted')",[$team]);}
function supervisor_invite(PDO $db,int $user,string $email):void {
 $team=supervisor_require($db,$user);$email=mb_strtolower(trim($email));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new CatalogException('Ingresá un correo válido.',422);
 $target=(int)stock_query($db,'SELECT id FROM users WHERE LOWER(email)=?',[$email])->fetchColumn();if(!$target)throw new CatalogException('Esa persona todavía no tiene una cuenta.',404);if($target===$user)throw new CatalogException('Elegí a otra persona para tu equipo.',422);
 $old=stock_query($db,'SELECT status FROM supervisor_members WHERE team_id=? AND user_id=?',[$team['id'],$target])->fetchColumn();if(in_array($old,['pending','accepted'],true))throw new CatalogException($old==='accepted'?'La persona ya es parte de tu equipo.':'La invitación ya está pendiente.',409);
 if((int)stock_query($db,"SELECT COUNT(*) FROM supervisor_members WHERE team_id=? AND status IN ('pending','accepted')",[$team['id']])->fetchColumn()>=200)throw new CatalogException('El equipo alcanzó su límite de integrantes.',422);
 stock_query($db,"INSERT INTO supervisor_members(team_id,user_id,status) VALUES(?,?,'pending') ON CONFLICT(team_id,user_id) DO UPDATE SET status='pending',revision=supervisor_members.revision+1,created_at=CURRENT_TIMESTAMP",[$team['id'],$target]);$revision=stock_query($db,'SELECT revision FROM supervisor_members WHERE team_id=? AND user_id=?',[$team['id'],$target])->fetchColumn();
 stock_query($db,'INSERT INTO notifications(user_id,event_key,type,title,body) VALUES(?,?,?,?,?)',[$target,'supervisor-invite:'.$team['id'].':'.$target.':'.$revision,'supervisor_invitation','Invitación de un supervisor',$team['name'].' quiere consultar tu stock. Aceptá o rechazá la invitación en Supervisores.']);
}
function supervisor_decide(PDO $db,int $user,int $team,int $revision,string $decision):void {
 if(!in_array($decision,['accept','decline','leave'],true))throw new CatalogException('Acción no válida.',422);$status=$decision==='accept'?'accepted':($decision==='decline'?'declined':'revoked');$expected=$decision==='leave'?'accepted':'pending';
 if($decision!=='leave'&&!stock_query($db,'SELECT 1 FROM supervisor_teams WHERE id=? AND active=1',[$team])->fetchColumn())throw new CatalogException('La invitación ya no está disponible.',409);
 if(!stock_query($db,'UPDATE supervisor_members SET status=?,revision=revision+1 WHERE team_id=? AND user_id=? AND revision=? AND status=?',[$status,$team,$user,$revision,$expected])->rowCount())throw new CatalogException('El vínculo cambió. Actualizá la lista.',409);
 if($decision==='accept'){$owner=stock_query($db,'SELECT owner_id FROM supervisor_teams WHERE id=?',[$team])->fetchColumn();stock_query($db,'INSERT INTO notifications(user_id,event_key,type,title,body) VALUES(?,?,?,?,?)',[$owner,'supervisor-joined:'.$team.':'.$user.':'.$revision,'supervisor_joined','Nuevo integrante en tu equipo',get_public_user_name(stock_query($db,'SELECT public_name,name FROM users WHERE id=?',[$user])->fetch()).' aceptó tu invitación.']);}
}
function supervisor_members(PDO $db,int $user):array {$t=supervisor_require($db,$user);$rows=stock_query($db,"SELECT m.user_id,m.status,m.revision,m.branch_scope,u.public_name,u.name FROM supervisor_members m JOIN users u ON u.id=m.user_id WHERE m.team_id=? AND m.status IN ('pending','accepted') ORDER BY u.public_name,u.id",[$t['id']])->fetchAll();foreach($rows as&$r){$r['name']=get_public_user_name($r);unset($r['public_name']);}unset($r);return $rows;}
function supervisor_member_locations(PDO $db,int $user,int $target):array {
 $t=supervisor_require($db,$user);$m=stock_query($db,"SELECT scope_revision AS revision,branch_scope FROM supervisor_members WHERE team_id=? AND user_id=? AND status='accepted'",[$t['id'],$target])->fetch();if(!$m)throw new CatalogException('El integrante ya no está disponible.',403);
 $visible=branch_visibility_sql($db,$user,'p.branch_id');$options=stock_query($db,"SELECT DISTINCT COALESCE(p.branch_id,0) AS id,COALESCE(b.name,'Sin sucursal') AS name FROM pallets p LEFT JOIN stock_branches b ON b.id=p.branch_id WHERE p.owner_id=? AND p.released=0 AND p.activated=1 AND $visible ORDER BY name",[$target])->fetchAll();
 $selected=stock_query($db,'SELECT branch_id FROM supervisor_member_branches WHERE team_id=? AND user_id=?',[$t['id'],$target])->fetchAll(PDO::FETCH_COLUMN);
 return ['revision'=>(int)$m['revision'],'all'=>$m['branch_scope']==='all','options'=>$options,'selected'=>array_map('intval',$selected)];
}
function supervisor_save_member_locations(PDO $db,int $user,int $target,int $revision,string $branches):void {
 $t=supervisor_require($db,$user);$available=supervisor_member_locations($db,$user,$target);$ids=$branches==='all'?[]:($branches===''?[]:supervisor_selection($branches,true));$chosen=[];foreach($ids as$id)$chosen[]=$id==='none'?0:(int)$id;
 $allowed=array_map('intval',array_column($available['options'],'id'));if(array_diff($chosen,$allowed))throw new CatalogException('Algún local ya no está disponible. Actualizá la selección.',422);
 if(!stock_query($db,"UPDATE supervisor_members SET branch_scope=?,scope_revision=scope_revision+1 WHERE team_id=? AND user_id=? AND scope_revision=? AND status='accepted'",[$branches==='all'?'all':'selected',$t['id'],$target,$revision])->rowCount())throw new CatalogException('El vínculo cambió. Actualizá el equipo.',409);
 stock_query($db,'DELETE FROM supervisor_member_branches WHERE team_id=? AND user_id=?',[$t['id'],$target]);foreach($chosen as$id)stock_query($db,'INSERT INTO supervisor_member_branches(team_id,user_id,branch_id) VALUES(?,?,?)',[$t['id'],$target,$id]);
}
function supervisor_remove(PDO $db,int $user,int $target,int $revision):void {$t=supervisor_require($db,$user);if(!stock_query($db,"UPDATE supervisor_members SET status='revoked',revision=revision+1 WHERE team_id=? AND user_id=? AND revision=? AND status IN ('accepted','pending')",[$t['id'],$target,$revision])->rowCount())throw new CatalogException('El vínculo cambió. Actualizá la lista.',409);}
function supervisor_selection(string $value,bool $branches=false):?array {
 if($value==='all')return null;$ids=array_values(array_unique(explode(',',$value)));if(!$ids||count($ids)>200)throw new CatalogException('Elegí al menos una opción y hasta 200.',422);foreach($ids as$id)if(!($branches&&$id==='none')&&!preg_match('/^[1-9][0-9]{0,14}$/D',$id))throw new CatalogException('Revisá la selección del equipo.',422);return $ids;
}
function supervisor_scope(PDO $db,int $user,array $input):array {
 $team=supervisor_require($db,$user);$where=["p.released=0","p.activated=1","EXISTS(SELECT 1 FROM supervisor_members m WHERE m.team_id=? AND m.user_id=p.owner_id AND m.status='accepted' AND (m.branch_scope='all' OR EXISTS(SELECT 1 FROM supervisor_member_branches mb WHERE mb.team_id=m.team_id AND mb.user_id=m.user_id AND mb.branch_id=COALESCE(p.branch_id,0))))",branch_visibility_sql($db,$user,'p.branch_id')];$args=[$team['id']];
 $members=supervisor_selection($input['members']??$input['member']??'all');if($members!==null){$marks=implode(',',array_fill(0,count($members),'?'));$accepted=(int)stock_query($db,"SELECT COUNT(*) FROM supervisor_members WHERE team_id=? AND status='accepted' AND user_id IN ($marks)",[$team['id'],...$members])->fetchColumn();if($accepted!==count($members))throw new CatalogException('Algún integrante ya no pertenece a tu equipo. Actualizá la lista.',403);$where[]="p.owner_id IN ($marks)";array_push($args,...$members);}
 $branches=supervisor_selection($input['branches']??$input['branch']??'all',true);if($branches!==null){$ids=array_values(array_filter($branches,fn($id)=>$id!=='none'));$parts=[];if(in_array('none',$branches,true))$parts[]='p.branch_id IS NULL';if($ids){$parts[]='p.branch_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';array_push($args,...$ids);}$where[]='('.implode(' OR ',$parts).')';}
 $expiry=$input['expiry']??'all';if(!in_array($expiry,['all','usable','expired','due'],true))throw new CatalogException('Vencimiento no válido.',422);$today=(new DateTimeImmutable('today',new DateTimeZone('America/Buenos_Aires')))->format('Y-m-d');
 return [implode(' AND ',$where),$args,$expiry,$today];
}
function supervisor_stock_where(PDO $db,int $user,array $input):array {
 [$where,$args,$expiry,$today]=supervisor_scope($db,$user,$input);
 if($expiry==='usable'){$where.=" AND (b.expires='' OR b.expires>=?)";$args[]=$today;}elseif($expiry==='expired'){$where.=" AND b.expires<>'' AND b.expires<?";$args[]=$today;}elseif($expiry==='due'){$where.=" AND b.expires<>'' AND b.expires<=?";$args[]=(new DateTimeImmutable($today))->modify('+'.stock_warning_days($db,$user).' days')->format('Y-m-d');}
 return [$where,$args,$today];
}
function supervisor_rows(PDO $db,int $user,array $input,string $tail=''):PDOStatement {
 [$where,$args,$today]=supervisor_stock_where($db,$user,$input);
 if(isset($input['group_key'])){if(($input['group']??'')==='palets'){$where.=' AND p.code=?';}else{$where.=' AND b.ean=?';}$args[]=$input['group_key'];}
 $args[]=$today;
 return stock_query($db,"SELECT b.id,b.ean,b.name,b.units,b.expires,b.kind,b.pack_size,b.inner_pack_size,p.id AS pallet_id,p.code,p.owner_id,s.name AS branch_name,u.public_name,u.name AS owner_name,c.name AS catalog_product,c.brand AS catalog_brand,c.quantity AS catalog_quantity FROM pallet_products b JOIN pallets p ON p.id=b.pallet_id JOIN users u ON u.id=p.owner_id LEFT JOIN stock_branches s ON s.id=p.branch_id LEFT JOIN products c ON c.ean=b.ean WHERE $where ORDER BY p.code,b.ean,CASE WHEN b.expires<>'' AND b.expires<? THEN 1 ELSE 0 END,b.expires,b.id $tail",$args);
}
function supervisor_inventory(PDO $db,int $user,array $input):array {
 $view=$input['view']??'mercaderia';if(!in_array($view,['palets','mercaderia'],true))throw new CatalogException('Vista no válida.',422);$offset=filter_var($input['offset']??'0',FILTER_VALIDATE_INT,['options'=>['min_range'=>0,'max_range'=>100000]]);if($offset===false)throw new CatalogException('Página no válida.',422);
 [$where,$args]=supervisor_stock_where($db,$user,$input);$key=$view==='palets'?'p.code':'b.ean';$from=" FROM pallet_products b JOIN pallets p ON p.id=b.pallet_id WHERE $where";
 $summary=stock_query($db,"SELECT COUNT(DISTINCT $key) AS groups,COALESCE(SUM(b.units),0) AS units".$from,$args)->fetch();
 $rows=stock_query($db,"SELECT $key AS group_key,MAX(b.ean) AS ean,MAX(b.name) AS name,SUM(b.units) AS units,COALESCE(MIN(CASE WHEN b.expires>=? THEN b.expires ELSE NULL END),MIN(NULLIF(b.expires,''))) AS expires,MAX(u.public_name) AS public_name,MAX(u.name) AS owner_name,MAX(s.name) AS branch_name,MAX(c.name) AS catalog_product,MAX(c.brand) AS catalog_brand,MAX(c.quantity) AS catalog_quantity FROM pallet_products b JOIN pallets p ON p.id=b.pallet_id JOIN users u ON u.id=p.owner_id LEFT JOIN stock_branches s ON s.id=p.branch_id LEFT JOIN products c ON c.ean=b.ean WHERE $where GROUP BY $key ORDER BY $key LIMIT 31 OFFSET $offset",[(new DateTimeImmutable('today',new DateTimeZone('America/Buenos_Aires')))->format('Y-m-d'),...$args])->fetchAll();$items=[];
 foreach(array_slice($rows,0,30)as$r)$items[]=['key'=>$r['group_key'],'ean'=>$r['ean'],'name'=>$view==='palets'?'Palet '.$r['group_key']:stock_product_names($r)['display_name'],'units'=>(int)$r['units'],'expires'=>$r['expires'],'owner'=>$view==='palets'?get_public_user_name(['public_name'=>$r['public_name'],'name'=>$r['owner_name']]):'','branch_name'=>$view==='palets'?$r['branch_name']:''];
 return ['items'=>$items,'has_more'=>count($rows)>30,'offset'=>$offset,'groups'=>(int)$summary['groups'],'units'=>(int)$summary['units']];
}
function supervisor_lots(PDO $db,int $user,array $input):array {
 if(!isset($input['group_key'])||!preg_match('/^[0-9]{8,13}$/D',$input['group_key'])||!in_array($input['group']??'',['palets','mercaderia'],true))throw new CatalogException('Producto o palet no válido.',422);$offset=filter_var($input['offset']??'0',FILTER_VALIDATE_INT,['options'=>['min_range'=>0,'max_range'=>100000]]);if($offset===false)throw new CatalogException('Página no válida.',422);$rows=supervisor_rows($db,$user,$input,"LIMIT 31 OFFSET $offset")->fetchAll();$items=[];foreach(array_slice($rows,0,30)as$r)$items[]=['ean'=>$r['ean'],'name'=>stock_product_names($r)['display_name'],'units'=>(int)$r['units'],'kind'=>$r['kind'],'pack_size'=>(int)$r['pack_size'],'inner_pack_size'=>(int)$r['inner_pack_size'],'expires'=>$r['expires'],'code'=>$r['code'],'branch_name'=>$r['branch_name'],'owner'=>get_public_user_name(['public_name'=>$r['public_name'],'name'=>$r['owner_name']])];return ['items'=>$items,'has_more'=>count($rows)>30,'offset'=>$offset];
}
function supervisor_totals(PDO $db,int $user,array $input):array {[$where,$args]=supervisor_stock_where($db,$user,$input);$totals=[];foreach(stock_query($db,"SELECT b.ean,SUM(b.units) AS units FROM pallet_products b JOIN pallets p ON p.id=b.pallet_id WHERE $where GROUP BY b.ean",$args)as$r)$totals[$r['ean']]=(int)$r['units'];return $totals;}
function supervisor_branches(PDO $db,int $user):array {[$where,$args]=supervisor_scope($db,$user,[]);return stock_query($db,"SELECT DISTINCT s.id,s.name FROM pallets p JOIN stock_branches s ON s.id=p.branch_id WHERE $where ORDER BY s.name,s.id",$args)->fetchAll();}
function supervisor_lists(PDO $db,int $user):array {$t=supervisor_require($db,$user);return stock_query($db,'SELECT id,name,row_count,created_at FROM supervisor_lists WHERE team_id=? ORDER BY id DESC',[$t['id']])->fetchAll();}
function supervisor_list(PDO $db,int $user,int $id,bool $source=false):array {$t=supervisor_require($db,$user);$list=stock_query($db,'SELECT id,name,sheet_path,ean_column,ean_rows,row_count'.($source?',source_base64':'').' FROM supervisor_lists WHERE id=? AND team_id=?',[$id,$t['id']])->fetch();if(!$list)throw new CatalogException('Esta lista no está disponible.',404);return $list;}
// Versioned import metadata, while preserving lists saved before header detection.
function supervisor_list_rows(array $list):array {$data=json_decode($list['ean_rows'],true,512,JSON_THROW_ON_ERROR);return isset($data['format'])?$data['rows']:$data;}
function supervisor_list_header(array $list):int {$data=json_decode($list['ean_rows'],true,512,JSON_THROW_ON_ERROR);return isset($data['format'])?(int)$data['header']:1;}
function supervisor_export_columns(array $input,bool $comparison=false):array {
 $available=['ean'=>'EAN','name'=>'Producto','uxb'=>'UXB','stock'=>'Stock (unidades)','expires'=>'Vencimientos (unidades por fecha)','pallets'=>'Palets (unidades por fecha)','branches'=>'Sucursales (unidades)','members'=>'Integrantes (unidades)'];
 $chosen=isset($input['columns'])?array_unique(explode(',',$input['columns'])):($comparison?['stock']:array_keys($available));if(!$chosen||in_array('', $chosen,true)||array_diff($chosen,array_keys($available)))throw new CatalogException('Elegí al menos una columna válida para descargar.',422);return array_intersect_key($available,array_flip($chosen));
}
function supervisor_export_lines(array $amounts,bool $dates=false):string {
 if($dates)uksort($amounts,fn($a,$b)=>strcmp($a?:'9999',$b?:'9999'));else ksort($amounts,SORT_NATURAL);
 $lines=[];foreach($amounts as$label=>$units){if($dates)$label=$label?(new DateTimeImmutable($label))->format('d/m/Y'):'Sin vencimiento';$lines[]=$label.': '.$units.($units===1?' unidad':' unidades');}return implode("\n",$lines);
}
function supervisor_export_groups(iterable $rows):array {
 $groups=[];$count=0;foreach($rows as$r){if(++$count>20000)throw new CatalogException('El detalle supera 20.000 lotes. Elegí menos integrantes o sucursales.',422);$ean=(string)$r['ean'];if(!isset($groups[$ean]))$groups[$ean]=['ean'=>$ean,'stock'=>0,'names'=>[],'uxbs'=>[],'packs'=>[],'unknown_uxb'=>0,'dates'=>[],'lots'=>[],'locations'=>[],'people'=>[]];$g=&$groups[$ean];$units=(int)$r['units'];$g['stock']+=$units;$g['names'][stock_product_names($r)['display_name']]=true;
 $pack=(int)$r['pack_size'];$inner=(int)($r['inner_pack_size']??0);if(in_array($r['kind'],['boxes','packs'],true)&&$pack>1){$label=($r['kind']==='boxes'?'Caja: ':'Bulto: ').$pack;if($r['kind']==='boxes'&&$inner>0&&$pack%$inner===0)$label.=' ('.intdiv($pack,$inner).' × '.$inner.')';$g['uxbs'][$label]=($g['uxbs'][$label]??0)+$units;$g['packs'][$pack]=true;}else $g['unknown_uxb']+=$units;
 $date=$r['expires']??'';$g['dates'][$date]=($g['dates'][$date]??0)+$units;$code=(string)$r['code'];$g['lots'][$code][$date]=($g['lots'][$code][$date]??0)+$units;$branch=$r['branch_name']?:'Sin sucursal';$g['locations'][$branch]=($g['locations'][$branch]??0)+$units;$person=get_public_user_name(['public_name'=>$r['public_name'],'name'=>$r['owner_name']]);$g['people'][$person]=($g['people'][$person]??0)+$units;unset($g);}
 $result=[];ksort($groups,SORT_STRING);foreach($groups as$ean=>$g){$pallets=[];ksort($g['lots'],SORT_STRING);foreach($g['lots']as$code=>$dates)foreach(explode("\n",supervisor_export_lines($dates,true))as$line)$pallets[]='Palet '.$code.' · '.$line;
 $uxb='';if($g['uxbs']){$uxb=count($g['packs'])===1&&!$g['unknown_uxb']?(int)array_key_first($g['packs']):supervisor_export_lines($g['uxbs']);if($g['unknown_uxb'])$uxb.="\n".'Sin UXB informada: '.$g['unknown_uxb'].' unidades';}
 $result[$ean]=['ean'=>(string)$ean,'name'=>implode("\n",array_keys($g['names'])),'uxb'=>$uxb,'stock'=>$g['stock'],'expires'=>supervisor_export_lines($g['dates'],true),'pallets'=>implode("\n",$pallets),'branches'=>supervisor_export_lines($g['locations']),'members'=>supervisor_export_lines($g['people'])];}return $result;
}
function supervisor_export_data(PDO $db,int $user,array $input,array $columns):array {
 if(array_keys($columns)===['stock']){$data=[];foreach(supervisor_totals($db,$user,$input)as$ean=>$units){if(count($data)>=20000)throw new CatalogException('El stock supera 20.000 productos. Elegí menos integrantes o sucursales.',422);$data[$ean]=['ean'=>(string)$ean,'stock'=>$units];}ksort($data,SORT_STRING);return $data;}
 return supervisor_export_groups(supervisor_rows($db,$user,$input,'LIMIT 20001'));
}
function supervisor_export_table(array $data,array $columns):array {$rows=[array_values($columns)];foreach($data as$item){$row=[];foreach($columns as$key=>$label)$row[]=$item[$key]??'';$rows[]=$row;}return $rows;}
